class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is AmEngine) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is AmFmUnavailableReason) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is AmHistoryMode) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is AmEventKind) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is AmPlatformInfo) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is AmFmAvailability) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is AmMlxLoadRequest) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is AmMlxModelInfo) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is AmToolCallWire) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is AmWireMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is AmSampling) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is AmKvConfig) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is AmMlxGenerateRequest) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is AmFmTool) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is AmFmGenerateRequest) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is AmToolResult) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is AmEvent) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is AmEventBatch) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : AmEngine.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : AmFmUnavailableReason.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : AmHistoryMode.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : AmEventKind.values[value];
      case 133:
        return AmPlatformInfo.decode(readValue(buffer)!);
      case 134:
        return AmFmAvailability.decode(readValue(buffer)!);
      case 135:
        return AmMlxLoadRequest.decode(readValue(buffer)!);
      case 136:
        return AmMlxModelInfo.decode(readValue(buffer)!);
      case 137:
        return AmToolCallWire.decode(readValue(buffer)!);
      case 138:
        return AmWireMessage.decode(readValue(buffer)!);
      case 139:
        return AmSampling.decode(readValue(buffer)!);
      case 140:
        return AmKvConfig.decode(readValue(buffer)!);
      case 141:
        return AmMlxGenerateRequest.decode(readValue(buffer)!);
      case 142:
        return AmFmTool.decode(readValue(buffer)!);
      case 143:
        return AmFmGenerateRequest.decode(readValue(buffer)!);
      case 144:
